    assign cpu_axi4_32b_w_to_cfg_regs = cpu_axi4_32b_wdest_valid && (cpu_axi4_32b_wdest_head == 1'd0);
    assign cpu_axi4_32b_w_to_apb_periph = cpu_axi4_32b_wdest_valid && (cpu_axi4_32b_wdest_head == 1'd1);

