    logic [0:0] cpu_axi4_64b_wdest_mem [16];
    logic [4:0] cpu_axi4_64b_wdest_wptr, cpu_axi4_64b_wdest_rptr;
    wire [0:0] cpu_axi4_64b_wdest_enc = 1'd0;
