        ((cfg_regs_axi_rid_bridge_id == 0) && cfg_regs_axi_rid_valid ? cfg_regs_axi_rresp : '0) |
        ((apb_periph_axi_rid_bridge_id == 0) && apb_periph_axi_rid_valid ? apb_periph_axi_rresp : '0);

    assign cpu_axi4_32b_r.last = 
