        (host_axil_32b_ar_gnt_apb_periph ? apb_periph_axi_arready : '0);

    assign host_axil_32b_r.id = 
        ((cfg_regs_axi_rid_bridge_id == 1) && cfg_regs_axi_rid_valid ? cfg_regs_axi_rid : '0) |
        ((apb_periph_axi_rid_bridge_id == 1) && apb_periph_axi_rid_valid ? apb_periph_axi_rid : '0);

    assign host_axil_32b_r.data = 
        ((cfg_regs_axi_rid_bridge_id == 1) && cfg_regs_axi_rid_valid ? cfg_regs_axi_rdata : 32'b0) |
        ((apb_periph_axi_rid_bridge_id == 1) && apb_periph_axi_rid_valid ? apb_periph_axi_rdata : 32'b0);

